      oct: { en: 'Oct', hi: 'अक्टूबर', mr: 'ऑक्टोबर', gu: 'ઓક્ટોબર', ta: 'அக்டோபர்', te: 'అక్టోబర్', kn: 'ಅಕ್ಟೋಬರ್', bn: 'অক্টোবর', ml: 'ഒക്ടോബർ' },
      nov: { en: 'Nov', hi: 'नवंबर', mr: 'नोव्हेंबर', gu: 'નવેમ્બર', ta: 'நவம்பர்', te: 'నవంబర్', kn: 'ನವೆಂಬರ್', bn: 'নভেম্বর', ml: 'നവംബർ' },
      dec: { en: 'Dec', hi: 'दिसंबर', mr: 'डिसेंबर', gu: 'ડિસેમ્બર', ta: 'டிசம்பர்', te: 'డిసెంబర్', kn: 'ಡಿಸೆಂಬರ್', bn: 'ডিসেম্বর', ml: 'ഡിസംബർ' },
