      hi: 'आहार नियंत्रण और रोसुवास्टेटिन से नियंत्रित कोलेस्ट्रॉल।',
      mr: 'योग्य आहार आणि रोसुव्हास्टॅटिनने नियंत्रित कोलेस्ट्रॉल.',
