      bn: '“৩ সপ্তাহ ধরে অবিরাম মাথাব্যথায় আক্রান্ত ৩৪ বছর বয়সী পুরুষ। স্ক্রিনের ব্যবহারের ফলে বৃদ্ধি পায়। নিউরোলজিক্যাল পরীক্ষা স্বাভাবিক। ব্রেন এমআরআই স্ক্যানের পরামর্শ দেওয়া হয়েছে এবং ব্যথানাশক ওষুধ দেওয়া হয়েছে।”',
