      ml: '“സീസണൽ ആസ്ത്മ ഫോളോ-അപ്പിനായി രോഗിയെ പരിശോധിച്ചു. നെഞ്ചിൽ കഫക്കെട്ടില്ല. പീക്ക് എക്സ്പിരേറ്ററി ഫ്ലോ 450 L/min. കൊളസ്ട്രോൾ അളവ് നിയന്ത്രണവിധേയം. ആവശ്യാനുസരണം സാൽബൂട്ടമോൾ ഇൻഹേലർ തുടരുക.”',
