      ta: 'நாப்ராக்ஸன் (Naproxen)',
      te: 'నాప్రాక్సెన్ (Naproxen)',
      kn: 'ನ್ಯಾಪ್ರೊಕ್ಸೆನ್ (Naproxen)',
      bn: 'ন্যাপ্রোক্সেন (Naproxen)',
      ml: 'നാപ്രോക്സെൻ (Naproxen)',
