      hi: 'पैरासिटामोल (Paracetamol)',
      mr: 'पॅरासिटामॉल (Paracetamol)',
      gu: 'પેરાસિટામોલ (Paracetamol)',
      ta: 'பாராசிட்டமால் (Paracetamol)',
      te: 'పారాసిటమాల్ (Paracetamol)',
      kn: 'ಪ್ಯಾರಸಿಟಮಾಲ್ (Paracetamol)',
      bn: 'প্যারাসিটামল (Paracetamol)',
      ml: 'പാരസെറ്റമോൾ (Paracetamol)',
