      ta: 'வேர்க்கடலை மற்றும் கொட்டைகள்',
      te: 'వేరుశెనగ మరియు గింజలు',
      kn: 'ಕಡಲೆಕಾಯಿ ಮತ್ತು ಬೀಜಗಳು',
